@SpringBootTest @AutoConfigureMockMvc
class PayrollCalculationIntegrationTest {
    static final UUID A=UUID.fromString("aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa"),B=UUID.fromString("bbbbbbbb-bbbb-bbbb-bbbb-bbbbbbbbbbbb"),ALPHA=UUID.fromString("11111111-1111-1111-1111-111111111111"),BETA=UUID.fromString("22222222-2222-2222-2222-222222222222");
    @Autowired MockMvc mvc;@Autowired PayrollLedgerEntryRepository ledger;@Autowired SalaryTemplateRepository templates;@Autowired PayRunEmployeeRepository payRunEmployees;@Autowired PayRunRepository payRuns;@Autowired CalculationLineRepository lines;@Autowired CalculationRepository calculations;@Autowired ComponentAssignmentRepository assignments;@Autowired CompensationProfileRepository profiles;@Autowired ComponentDefinitionRepository definitions;@Autowired PayrollEmployeeRepository employees;@Autowired PayrollWorkspaceRepository workspaces;
    @MockitoBean PayrollAuthorityClient authority;@MockitoBean WorkforceEmployeeVerifier workforce;@MockitoBean PayrollProcessingEntitlementGate entitlement;

    @BeforeEach void setup(){ledger.deleteAll();payRunEmployees.deleteAll();payRuns.deleteAll();lines.deleteAll();calculations.deleteAll();assignments.deleteAll();profiles.deleteAll();templates.deleteAll();definitions.deleteAll();employees.deleteAll();workspaces.deleteAll();when(authority.validate(anyString(),anyString(),any(),nullable(String.class))).thenAnswer(i->context(i.getArgument(0),i.getArgument(1),i.getArgument(3)));when(workforce.verify(anyString(),any())).thenAnswer(i->new WorkforceEmployeeVerifier.Verification(i.getArgument(0),true,WorkforceEmploymentStatus.ACTIVE));doNothing().when(entitlement).requireProcessing(any());}

    @Test void fixedPercentageTotalsExplicitBasesRoundingAndOneTimeAreDeterministic()throws Exception{employee("a","alpha","owner","EMP-1");component("a","alpha","owner","BASE","Base", "EARNING","FIXED_AMOUNT","RECURRING");component("a","alpha","owner","HOUSING","Housing","EARNING","FIXED_AMOUNT","RECURRING");component("a","alpha","owner","BONUS","Bonus","EARNING","PERCENTAGE","ONE_TIME");component("a","alpha","owner","RETIREMENT","Retirement","DEDUCTION","PERCENTAGE","RECURRING");component("a","alpha","owner","HEALTH","Health","DEDUCTION","FIXED_AMOUNT","RECURRING");profile("a","alpha","owner","EMP-1","P-1","2026-01-01",null,"BASE", "5000","HOUSING","1000","BONUS","10","RETIREMENT","5","HEALTH","100");calculate("a","alpha","owner","EMP-1","2026-09-01").andExpect(status().isCreated()).andExpect(jsonPath("$.grossAmount").value(6600.0)).andExpect(jsonPath("$.deductionAmount").value(430.0)).andExpect(jsonPath("$.netAmount").value(6170.0)).andExpect(jsonPath("$.lines[1].componentKey").value("BONUS")).andExpect(jsonPath("$.lines[1].calculatedAmount").value(600.0)).andExpect(jsonPath("$.lines[1].occurrence").value("ONE_TIME")).andExpect(jsonPath("$.lines[4].calculatedAmount").value(330.0));calculate("a","alpha","admin","EMP-1","2026-09-01").andExpect(jsonPath("$.grossAmount").value(6600.0)).andExpect(jsonPath("$.netAmount").value(6170.0));assertThat(calculations.count()).isEqualTo(2);}

    @Test void selectsExactHistoricalFutureAndInclusiveBoundaries()throws Exception{employee("a","alpha","owner","EMP-1");component("a","alpha","owner","BASE","Base","EARNING","FIXED_AMOUNT","RECURRING");profile("a","alpha","owner","EMP-1","H1","2026-01-01","2026-06-30","BASE","100");profile("a","alpha","owner","EMP-1","H2","2026-07-01",null,"BASE","200");calculate("a","alpha","owner","EMP-1","2025-12-31").andExpect(status().isNotFound());calculate("a","alpha","owner","EMP-1","2026-01-01").andExpect(jsonPath("$.grossAmount").value(100.0));calculate("a","alpha","owner","EMP-1","2026-06-30").andExpect(jsonPath("$.grossAmount").value(100.0));calculate("a","alpha","owner","EMP-1","2026-07-01").andExpect(jsonPath("$.grossAmount").value(200.0));}

    @Test void percentageCalculationUsesScaleFourHalfUpRounding()throws Exception{employee("a","alpha","owner","EMP-ROUND");component("a","alpha","owner","BASE","Base","EARNING","FIXED_AMOUNT","RECURRING");component("a","alpha","owner","BONUS","Bonus","EARNING","PERCENTAGE","RECURRING");profile("a","alpha","owner","EMP-ROUND","ROUND","2026-01-01",null,"BASE","1","BONUS","33.3333");calculate("a","alpha","owner","EMP-ROUND","2026-01-01").andExpect(status().isCreated()).andExpect(jsonPath("$.grossAmount").value(1.3333)).andExpect(jsonPath("$.lines[1].calculatedAmount").value(0.3333));}

    @Test void calculationSnapshotsSurviveDefinitionAndProfileChanges()throws Exception{employee("a","alpha","owner","EMP-1");component("a","alpha","owner","BASE","Original Name","EARNING","FIXED_AMOUNT","RECURRING");profile("a","alpha","owner","EMP-1","OLD","2026-01-01","2026-06-30","BASE","100");calculate("a","alpha","owner","EMP-1","2026-06-01").andExpect(status().isCreated()).andExpect(jsonPath("$.lines[0].displayName").value("Original Name"));request(patch("/api/payroll/components/BASE").contentType(MediaType.APPLICATION_JSON).content("{\"displayName\":\"Renamed\"}"),"a","alpha","owner").andExpect(status().isOk());request(delete("/api/payroll/components/BASE"),"a","alpha","owner").andExpect(status().isOk());request(patch("/api/payroll/components/BASE").contentType(MediaType.APPLICATION_JSON).content("{\"status\":\"ACTIVE\"}"),"a","alpha","owner").andExpect(status().isOk());profile("a","alpha","owner","EMP-1","NEW","2026-07-01",null,"BASE","999");calculate("a","alpha","owner","EMP-1","2026-07-01").andExpect(status().isCreated()).andExpect(jsonPath("$.lines[0].displayName").value("Renamed"));request(get("/api/payroll/employees/EMP-1/calculations"),"a","alpha","owner").andExpect(status().isOk()).andExpect(jsonPath("$[0].grossAmount").value(100.0)).andExpect(jsonPath("$[0].lines[0].displayName").value("Original Name")).andExpect(jsonPath("$[0].lines[0].configuredValue").value(100.0));}

    @Test void excessiveDeductionsAndMissingConfigurationDoNotPersist()throws Exception{employee("a","alpha","owner","EMP-1");calculate("a","alpha","owner","EMP-1","2026-01-01").andExpect(status().isNotFound());component("a","alpha","owner","BASE","Base","EARNING","FIXED_AMOUNT","RECURRING");component("a","alpha","owner","DEDUCT","Deduct","DEDUCTION","FIXED_AMOUNT","RECURRING");profile("a","alpha","owner","EMP-1","BAD","2026-01-01",null,"BASE","100","DEDUCT","101");calculate("a","alpha","owner","EMP-1","2026-01-01").andExpect(status().isConflict());assertThat(calculations.count()).isZero();}

    @Test void authorizationEntitlementTenantIsolationAndInjectionFailClosed()throws Exception{employee("a","alpha","owner","EMP-1");employee("b","beta","owner","EMP-1");component("a","alpha","owner","BASE","Base","EARNING","FIXED_AMOUNT","RECURRING");profile("a","alpha","owner","EMP-1","P","2026-01-01",null,"BASE","100");calculate("b","beta","owner","EMP-1","2026-01-01").andExpect(status().isNotFound());calculate("a","alpha","manager","EMP-1","2026-01-01").andExpect(status().isForbidden());calculate("a","alpha","member","EMP-1","2026-01-01").andExpect(status().isForbidden());mvc.perform(post("/api/payroll/employees/EMP-1/calculations").contentType(MediaType.APPLICATION_JSON).content("{\"calculationDate\":\"2026-01-01\"}")).andExpect(status().isUnauthorized());String id=B.toString();request(post("/api/payroll/employees/EMP-1/calculations").contentType(MediaType.APPLICATION_JSON).content("{\"calculationDate\":\"2026-01-01\",\"currency\":\"EUR\",\"workspaceId\":\""+id+"\",\"organizationId\":\""+id+"\",\"userId\":\""+id+"\",\"calculationId\":\""+id+"\",\"role\":\"ADMIN\"}"),"a","alpha","owner").andExpect(status().isBadRequest());doThrow(new com.lexorion.payroll.api.PayrollException(403,"missing entitlement")).when(entitlement).requireProcessing(any());calculate("a","alpha","owner","EMP-1","2026-01-01").andExpect(status().isForbidden());assertThat(calculations.count()).isZero();}

    @Test void concurrentProfileCreationAndCalculationProduceAConsistentSnapshot()throws Exception{employee("a","alpha","owner","EMP-1");component("a","alpha","owner","BASE","Base","EARNING","FIXED_AMOUNT","RECURRING");profile("a","alpha","owner","EMP-1","CURRENT","2026-01-01","2026-06-30","BASE","100");CompletableFuture<Integer>calculation=CompletableFuture.supplyAsync(()->calculationStatus("2026-05-01"));CompletableFuture<Integer>futureProfile=CompletableFuture.supplyAsync(this::futureProfileStatus);assertThat(List.of(calculation.join(),futureProfile.join())).containsOnly(201);assertThat(calculations.findByWorkspaceIdAndEmployeeCodeOrderByCalculationDateAscCreatedAtAsc(A,"EMP-1")).singleElement().extracting(c->c.getGrossAmount()).isEqualTo(new java.math.BigDecimal("100.0000"));assertThat(profiles.count()).isEqualTo(2);}

    @Test void calculationsAreImmutableAndRetainedInOpenApi()throws Exception{employee("a","alpha","owner","EMP-1");component("a","alpha","owner","BASE","Base","EARNING","FIXED_AMOUNT","RECURRING");profile("a","alpha","owner","EMP-1","P","2026-01-01",null,"BASE","100");calculate("a","alpha","owner","EMP-1","2026-01-01").andExpect(status().isCreated()).andExpect(jsonPath("$.id").doesNotExist()).andExpect(jsonPath("$.workspaceId").doesNotExist());request(patch("/api/payroll/employees/EMP-1/calculations").contentType(MediaType.APPLICATION_JSON).content("{}"),"a","alpha","owner").andExpect(status().isMethodNotAllowed());request(delete("/api/payroll/employees/EMP-1/calculations"),"a","alpha","owner").andExpect(status().isMethodNotAllowed());mvc.perform(get("/v3/api-docs")).andExpect(status().isOk()).andExpect(jsonPath("$.info.version").value("10F")).andExpect(jsonPath("$.paths['/api/payroll/employees/{employeeCode}/calculations'].post").exists());}

    private void employee(String w,String org,String token,String code)throws Exception{request(post("/api/payroll/employees").contentType(MediaType.APPLICATION_JSON).content("{\"employeeCode\":\""+code+"\",\"status\":\"ACTIVE\",\"currency\":\"USD\",\"payFrequency\":\"MONTHLY\",\"effectiveFrom\":\"2026-01-01\"}"),w,org,token).andExpect(status().isCreated());}private void component(String w,String org,String token,String key,String name,String category,String type,String occurrence)throws Exception{request(post("/api/payroll/components").contentType(MediaType.APPLICATION_JSON).content("{\"componentKey\":\""+key+"\",\"displayName\":\""+name+"\",\"category\":\""+category+"\",\"amountType\":\""+type+"\",\"occurrenceType\":\""+occurrence+"\",\"taxability\":\"TAXABLE\",\"status\":\"ACTIVE\"}"),w,org,token).andExpect(status().isCreated());}private void profile(String w,String org,String token,String employee,String key,String from,String to,String...components)throws Exception{StringJoiner values=new StringJoiner(",");for(int i=0;i<components.length;i+=2)values.add("{\"componentKey\":\""+components[i]+"\",\"value\":"+components[i+1]+"}");String body="{\"profileKey\":\""+key+"\",\"currency\":\"USD\",\"effectiveFrom\":\""+from+"\""+(to==null?"":",\"effectiveTo\":\""+to+"\"")+",\"status\":\"ACTIVE\",\"components\":["+values+"]}";request(post("/api/payroll/employees/"+employee+"/compensation").contentType(MediaType.APPLICATION_JSON).content(body),w,org,token).andExpect(status().isCreated());}private ResultActions calculate(String w,String org,String token,String employee,String date)throws Exception{return request(post("/api/payroll/employees/"+employee+"/calculations").contentType(MediaType.APPLICATION_JSON).content("{\"calculationDate\":\""+date+"\"}"),w,org,token);}private int calculationStatus(String date){try{return calculate("a","alpha","owner","EMP-1",date).andReturn().getResponse().getStatus();}catch(Exception e){throw new IllegalStateException(e);}}private int futureProfileStatus(){try{String body="{\"profileKey\":\"FUTURE\",\"currency\":\"USD\",\"effectiveFrom\":\"2026-07-01\",\"status\":\"ACTIVE\",\"components\":[{\"componentKey\":\"BASE\",\"value\":200}]}";return request(post("/api/payroll/employees/EMP-1/compensation").contentType(MediaType.APPLICATION_JSON).content(body),"a","alpha","owner").andReturn().getResponse().getStatus();}catch(Exception e){throw new IllegalStateException(e);}}private ResultActions request(org.springframework.test.web.servlet.request.MockHttpServletRequestBuilder r,String w,String org,String token)throws Exception{return mvc.perform(r.header("Host","horizon.lexorion.in").header("Authorization","Bearer "+token).header("X-Lexorion-Workspace",w).header("X-Lexorion-Organization",org));}private TrustedPayrollContext context(String w,String token,String org){if((!w.equals("a")&&!w.equals("b"))||!org.equals(w.equals("a")?"alpha":"beta"))throw new IllegalArgumentException();return new TrustedPayrollContext(w.equals("a")?A:B,w,w.equals("a")?ALPHA:BETA,org,token.contains("manager")?"MANAGER":token.contains("member")?"EMPLOYEE":token.contains("admin")?"ADMIN":"ADMIN",UUID.nameUUIDFromBytes((w+":"+token).getBytes(StandardCharsets.UTF_8)));}
}
